<template>
  <div class="page-head"><div><div class="eyebrow">{{config.eyebrow}}</div><h1>{{config.title}}</h1><p>{{config.description}}</p></div><el-button v-if="canCreate" type="primary" size="large" @click="openCreate">＋ {{config.create}}</el-button></div>
  <el-alert v-if="failure" :title="failure" type="error" show-icon :closable="false" class="page-error" />
  <template v-if="section==='roles'">
    <div class="role-grid"><article v-for="row in rows" :key="row.id" class="panel role-card"><span class="role-symbol">◇</span><h3>{{row.name}}</h3><code>{{row.tag}}</code><p>{{roleDescriptions[row.tag]}}</p><div class="permission-list"><span v-for="permission in row.permissions" :key="permission" class="badge soft">{{permission==='*'?'全部权限':permission}}</span></div></article></div>
    <div class="inline-note">角色权限由服务端维护；调整账号角色后，原登录会话会立即撤销。</div>
  </template>
  <section v-else class="panel workspace-panel">
    <div class="toolbar"><div class="search-controls"><el-input v-if="section!=='audits'" v-model="query" :placeholder="config.placeholder||'输入编号或名称搜索'" clearable @keyup.enter="search" @clear="search"/><el-select v-if="states.length" v-model="status" placeholder="全部状态" clearable @change="search"><el-option v-for="item in states" :key="item[0]" :value="item[0]" :label="item[1]"/></el-select><el-button v-if="section!=='audits'" @click="search">查询</el-button><el-button @click="load">刷新</el-button><el-button v-if="route.query.contractId" @click="router.push('/bills')">取消合同筛选</el-button></div><span class="record-count">共 <b>{{total}}</b> 条记录</span></div>
    <el-table v-loading="loading" :data="rows" stripe :empty-text="loading?'加载中…':'暂无记录，添加第一条资料开始使用'" row-key="id">
      <el-table-column v-for="column in config.columns" :key="column.key" :prop="column.key" :label="column.label" :min-width="column.width||140" :show-overflow-tooltip="true">
        <template #default="{row}"><span v-if="column.money" class="money">¥ {{money(row[column.key])}}</span><span v-else-if="column.key==='status'" class="badge" :class="badge(row.status)">{{stateLabel(row.status)}}</span><span v-else-if="column.key==='roles'">{{row.roles?.map(role=>roleNames[role]||role).join('、')}}</span><code v-else-if="column.code">{{row[column.key]}}</code><span v-else>{{row[column.key]||'—'}}</span></template>
      </el-table-column>
      <el-table-column v-if="hasActions" label="操作" :min-width="section==='contracts'?210:190" fixed="right"><template #default="{row}">
        <template v-if="['houses','tenants'].includes(section)&&canWrite"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="danger" @click="archive(row)">归档</el-button></template>
        <template v-if="section==='contracts'"><el-button link type="primary" @click="router.push({path:'/bills',query:{contractId:row.id}})">查看账单</el-button><el-button v-if="canWrite&&row.status==='ACTIVE'" link type="danger" @click="closeContract(row)">退租结算</el-button></template>
        <template v-if="section==='bills'"><el-button v-if="canCollect&&!['PAID','CANCELLED'].includes(row.status)" link type="primary" @click="openPayment(row)">登记收款</el-button><el-button link type="primary" @click="showPayments(row)">收款流水</el-button></template>
        <el-button v-if="section==='users'" link type="primary" :disabled="row.id===store.state.user?.id" @click="openAccess(row)">角色与状态</el-button>
      </template></el-table-column>
    </el-table>
    <div class="pagination"><span>数据实时更新 · 金额单位：人民币元</span><el-pagination background layout="sizes, prev, pager, next" :total="total" :current-page="page" :page-size="size" :page-sizes="[10,20,50]" @current-change="value=>{page=value;load()}" @size-change="value=>{size=value;search()}"/></div>
  </section>

  <el-dialog v-model="dialog" :title="dialogTitle" width="590px" :close-on-click-modal="false" destroy-on-close>
    <el-alert v-if="section==='contracts'" title="签约后立即占用房源，并按起租日生成各月账单。押金仅作合同约定记录。" type="info" :closable="false" class="form-note"/>
    <el-form :model="form" label-position="top" @submit.prevent>
      <template v-if="section==='houses'"><div class="form-grid"><el-form-item label="房源编号"><el-input v-model="form.code" placeholder="如 A-101" maxlength="32"/></el-form-item><el-form-item label="房源名称"><el-input v-model="form.title" placeholder="如 青秀·采光一居" maxlength="80"/></el-form-item></div><el-form-item label="详细地址"><el-input v-model="form.address" maxlength="200"/></el-form-item><div class="form-grid"><el-form-item label="建筑面积（平方米）"><el-input-number v-model="form.area" :min="1" :precision="2" :max="9999.99"/></el-form-item><el-form-item label="月租金（元）"><el-input-number v-model="form.monthlyRent" :min="0.01" :precision="2" :max="9999999.99"/></el-form-item><el-form-item label="约定押金（元）"><el-input-number v-model="form.deposit" :min="0" :precision="2" :max="9999999.99"/></el-form-item><el-form-item :label="occupiedEdit?'出租状态由合同维护':'房源状态'"><el-select v-model="form.status" :disabled="occupiedEdit"><el-option label="空置 / 可出租" value="VACANT"/><el-option label="下架 / 暂不出租" value="OFFLINE"/></el-select></el-form-item></div></template>
      <template v-if="section==='tenants'"><div class="form-grid"><el-form-item label="租客姓名"><el-input v-model="form.name" maxlength="40"/></el-form-item><el-form-item label="手机号码"><el-input v-model="form.phone" maxlength="11"/></el-form-item></div><el-form-item label="邮箱（选填）"><el-input v-model="form.email" maxlength="100"/></el-form-item><el-form-item label="备注（选填）"><el-input v-model="form.remark" type="textarea" maxlength="200" show-word-limit/></el-form-item></template>
      <template v-if="section==='contracts'"><el-form-item label="选择可出租房源"><el-select v-model="form.houseId" filterable placeholder="请选择空置房源"><el-option v-for="house in houseOptions" :key="house.id" :value="house.id" :label="house.code+' · '+house.title+' / ¥'+money(house.monthlyRent)"/></el-select></el-form-item><el-form-item label="签约租客"><el-select v-model="form.tenantId" filterable placeholder="请选择已登记租客"><el-option v-for="tenant in tenantOptions" :key="tenant.id" :value="tenant.id" :label="tenant.name+' · '+tenant.phone"/></el-select></el-form-item><div class="form-grid"><el-form-item label="起租日"><el-date-picker v-model="form.startDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="租期（月）"><el-input-number v-model="form.months" :min="1" :max="24"/></el-form-item></div><div class="inline-note">合同保留签约时租金快照，房源后续调价不会改变历史账单。</div></template>
      <template v-if="section==='users'"><div class="form-grid"><el-form-item label="登录账号"><el-input v-model="form.username" placeholder="5—30 位字母、数字或下划线"/></el-form-item><el-form-item label="显示名称"><el-input v-model="form.nickname" maxlength="30"/></el-form-item></div><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password placeholder="8—64 位字符"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option v-for="(label,value) in roleNames" :key="value" :value="value" :label="label"/></el-select></el-form-item><div class="form-grid"><el-form-item label="邮箱（选填）"><el-input v-model="form.email"/></el-form-item><el-form-item label="手机（选填）"><el-input v-model="form.phone"/></el-form-item></div></template>
    </el-form>
    <template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{section==='contracts'?'确认签约':'保存资料'}}</el-button></template>
  </el-dialog>
  <el-dialog v-model="paymentDialog" title="登记收款" width="490px" :close-on-click-modal="false"><div class="payment-brief"><span>{{selected?.houseTitle}} · {{selected?.tenantName}}</span><strong>待收 ¥ {{money(Number(selected?.amount)-Number(selected?.paidAmount))}}</strong></div><el-form label-position="top"><el-form-item label="本次收款金额（元）"><el-input-number v-model="payment.amount" :min="0.01" :max="Number(selected?.amount)-Number(selected?.paidAmount)" :precision="2"/></el-form-item><el-form-item label="收款方式"><el-select v-model="payment.method"><el-option label="银行转账" value="BANK"/><el-option label="现金" value="CASH"/><el-option label="其他线下方式" value="OTHER"/></el-select></el-form-item><el-form-item label="收款备注"><el-input v-model="payment.note" maxlength="200"/></el-form-item></el-form><div class="inline-note">这是线下收款记录，不会发起真实资金扣款。</div><template #footer><el-button @click="paymentDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="receive">确认收款</el-button></template></el-dialog>
  <el-dialog v-model="paymentsDialog" title="收款流水" width="720px"><el-table :data="payments" empty-text="还没有收款记录"><el-table-column prop="createdAt" label="收款时间" min-width="170"/><el-table-column label="金额" width="125"><template #default="{row}">¥ {{money(row.amount)}}</template></el-table-column><el-table-column prop="method" label="方式" width="90"/><el-table-column prop="actor" label="登记人" width="100"/><el-table-column prop="note" label="备注" min-width="150"/></el-table></el-dialog>
  <el-dialog v-model="accessDialog" title="账号角色与状态" width="460px"><el-alert title="保存后将撤销该账号原有会话，需要重新登录。" type="info" :closable="false" class="form-note"/><el-form label-position="top"><el-form-item label="角色"><el-select v-model="access.role"><el-option v-for="(label,value) in roleNames" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="状态"><el-radio-group v-model="access.status"><el-radio value="0">启用</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="accessDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAccess">保存并撤销旧会话</el-button></template></el-dialog>
</template>
<script setup>
import { computed,onMounted,reactive,ref,watch } from "vue";
import { useRoute,useRouter } from "vue-router";
import { useStore } from "vuex";
import { ElMessage,ElMessageBox } from "element-plus";
import api from "@/api";
const route=useRoute(),router=useRouter(),store=useStore();const section=route.meta.section;
const column=(key,label,width,money=false,code=false)=>({key,label,width,money,code});
// 页面列与 API 字段一一对应，避免每个业务模块复制同样的分页加载逻辑。
const settings={
 houses:{title:"房源档案",eyebrow:"PROPERTY INVENTORY",description:"统一维护房源资料，准确掌握每一套房的出租状态。",create:"新增房源",path:"/houses",columns:[column("code","房源编号",120,false,true),column("title","房源名称",175),column("address","地址",200),column("area","面积 / ㎡",100),column("monthlyRent","月租金",130,true),column("status","状态",105)]},
 tenants:{title:"租客档案",eyebrow:"TENANT DIRECTORY",description:"联系信息与签约关系集中管理，历史合同保留可追溯。",create:"登记租客",path:"/tenants",placeholder:"搜索租客姓名或手机号码",columns:[column("name","租客姓名",130),column("phone","手机号码",150),column("email","邮箱",210),column("remark","备注",200),column("createdAt","登记时间",180)]},
 contracts:{title:"租赁合同",eyebrow:"LEASE AGREEMENTS",description:"从签约到退租，房源占用与账单生成同步完成。",create:"签订合同",path:"/contracts",columns:[column("contractNo","合同编号",225,false,true),column("houseTitle","房源",170),column("tenantName","租客",110),column("startDate","起租日",125),column("endDate","到期日",125),column("monthlyRent","月租金",125,true),column("status","状态",100)]},
 bills:{title:"账单与收款",eyebrow:"BILLING & COLLECTION",description:"每月应收、分次实收与流水记录，金额清晰可核对。",path:"/bills",columns:[column("period","账期",105),column("houseTitle","房源",170),column("tenantName","租客",110),column("dueDate","到期日",125),column("amount","应收",120,true),column("paidAmount","实收",120,true),column("status","状态",110)]},
 users:{title:"账号管理",eyebrow:"ACCOUNT MANAGEMENT",description:"按职责分配账号权限，角色与状态调整即时生效。",create:"新增账号",path:"/system/users",placeholder:"搜索账号或显示名称",columns:[column("username","登录账号",150),column("nickname","显示名称",130),column("roles","角色",180),column("email","邮箱",220),column("status","账号状态",110)]},
 roles:{title:"角色权限",eyebrow:"ROLES & PERMISSIONS",description:"三种职责边界，所有权限在服务端校验。",path:"/system/roles",columns:[]},
 audits:{title:"操作日志",eyebrow:"AUDIT TRAIL",description:"记录资料、合同、收款与账号变更，支持按请求编号定位。",path:"/system/audits",columns:[column("createdAt","操作时间",185),column("actor","操作账号",130),column("action","操作类型",205,false,true),column("target","业务对象",220),column("requestId","请求编号",255,false,true)]}
};
const config=settings[section],rows=ref([]),total=ref(0),page=ref(1),size=ref(10),query=ref(""),status=ref(""),loading=ref(false),failure=ref("");
const canWrite=computed(()=>store.getters.can("rental:write")),canCollect=computed(()=>store.getters.can("finance:collect"));
const canCreate=computed(()=>!!config.create&&(section==="users"?store.getters.can("system:manage"):canWrite.value));
const hasActions=computed(()=>["contracts","bills","users"].includes(section)||(["houses","tenants"].includes(section)&&canWrite.value));
const stateNames={VACANT:"空置中",OCCUPIED:"已出租",OFFLINE:"已下架",ACTIVE:"生效中",CLOSED:"已结束",UNPAID:"未收款",PARTIAL:"部分收款",PAID:"已结清",CANCELLED:"已取消","0":"启用","1":"停用"};
const stateLabel=value=>stateNames[value]||value;const badge=value=>["VACANT","ACTIVE","PAID","0"].includes(value)?"soft":["PARTIAL","UNPAID"].includes(value)?"warn":"neutral";
const states=computed(()=>({houses:[["VACANT","空置中"],["OCCUPIED","已出租"],["OFFLINE","已下架"]],contracts:[["ACTIVE","生效中"],["CLOSED","已结束"]],bills:[["UNPAID","未收款"],["PARTIAL","部分收款"],["PAID","已结清"],["CANCELLED","已取消"]]})[section]||[]);
const roleNames={admin:"管理员",operator:"租赁运营",viewer:"只读观察员"};const roleDescriptions={admin:"维护全部租赁资料与账号权限，查看操作日志。",operator:"维护房源与租客、签约退租、登记线下收款。",viewer:"查看经营概览、房源、租客、合同、账单与流水。"};
const money=value=>Number(value||0).toLocaleString("zh-CN",{minimumFractionDigits:2,maximumFractionDigits:2});
async function load(){loading.value=true;failure.value="";try{const data=await api.get(config.path,{params:{page:page.value,size:size.value,query:query.value,status:status.value,contractId:route.query.contractId}});rows.value=Array.isArray(data)?data:data.records;total.value=Array.isArray(data)?data.length:data.total;}catch(error){failure.value=error.message;}finally{loading.value=false;}}
function search(){page.value=1;load();}
// 同一账单路由只改变查询参数时，取消合同筛选也必须重新请求数据。
watch(()=>route.query.contractId,search);
const dialog=ref(false),dialogTitle=ref(""),saving=ref(false),form=reactive({}),occupiedEdit=ref(false),houseOptions=ref([]),tenantOptions=ref([]);
function reset(value){for(const key of Object.keys(form))delete form[key];Object.assign(form,value);}
async function openCreate(){occupiedEdit.value=false;reset(({houses:{code:"",title:"",address:"",area:40,monthlyRent:1800,deposit:1800,status:"VACANT",version:0},tenants:{name:"",phone:"",email:"",remark:""},contracts:{houseId:null,tenantId:null,startDate:new Date().toLocaleDateString("sv-SE"),months:6},users:{username:"",nickname:"",password:"",role:"operator",email:"",phone:""}})[section]);dialogTitle.value=config.create;
  if(section==="contracts"){try{const [houses,tenants]=await Promise.all([api.get("/houses",{params:{status:"VACANT",size:100}}),api.get("/tenants",{params:{size:100}})]);houseOptions.value=houses.records;tenantOptions.value=tenants.records;}catch(error){ElMessage.error(error.message);return;}}
  dialog.value=true;
}
function openEdit(row){reset({...row,status:row.status==="OCCUPIED"?"VACANT":row.status});occupiedEdit.value=row.status==="OCCUPIED";dialogTitle.value="编辑"+(section==="houses"?"房源":"租客");dialog.value=true;}
async function save(){if(saving.value)return;saving.value=true;try{if(form.id)await api.put(config.path+"/"+form.id,form);else await api.post(config.path,form);dialog.value=false;ElMessage.success(section==="contracts"?"签约成功，月账单已生成":"资料已保存");search();}catch(error){ElMessage.error(error.message);}finally{saving.value=false;}}
async function archive(row){try{await ElMessageBox.confirm("归档后将从当前档案中隐藏，历史合同与流水会保留。确认继续？","归档确认",{type:"warning",confirmButtonText:"确认归档",cancelButtonText:"取消"});await api.delete(config.path+"/"+row.id);ElMessage.success("已归档");load();}catch(error){if(error instanceof Error)ElMessage.error(error.message);}}
async function closeContract(row){try{await ElMessageBox.confirm("系统将校验到期欠款；结清后取消未来未收账单并释放房源。确认退租？","退租结算",{confirmButtonText:"确认退租",cancelButtonText:"取消"});await api.post("/contracts/"+row.id+"/close");ElMessage.success("退租完成，房源已恢复空置");load();}catch(error){if(error instanceof Error)ElMessage.error(error.message);}}
const selected=ref(null),paymentDialog=ref(false),paymentsDialog=ref(false),payments=ref([]),payment=reactive({});
function openPayment(row){selected.value=row;Object.assign(payment,{amount:Number(row.amount)-Number(row.paidAmount),method:"BANK",note:"",requestId:"PAY-"+crypto.randomUUID()});paymentDialog.value=true;}
// 网络失败后保留幂等号，重试同一笔登记不会产生重复流水。
async function receive(){if(saving.value)return;saving.value=true;try{await api.post("/bills/"+selected.value.id+"/payments",payment);paymentDialog.value=false;ElMessage.success("收款已登记");load();}catch(error){ElMessage.error(error.message);}finally{saving.value=false;}}
async function showPayments(row){try{payments.value=await api.get("/bills/"+row.id+"/payments");paymentsDialog.value=true;}catch(error){ElMessage.error(error.message);}}
const accessDialog=ref(false),access=reactive({});function openAccess(row){Object.assign(access,{id:row.id,role:row.roles?.[0]||"viewer",status:row.status});accessDialog.value=true;}
async function saveAccess(){if(saving.value)return;saving.value=true;try{await api.put("/system/users/"+access.id+"/access",{role:access.role,status:access.status});accessDialog.value=false;ElMessage.success("角色与状态已更新");load();}catch(error){ElMessage.error(error.message);}finally{saving.value=false;}}
onMounted(load);
</script>
